-- Start To Up founding-company relationship for ResKonnect.
-- The logo is embedded as a compact WebP data URI so the public showcase does not depend on a third-party image host.

alter table public.partner_showcase drop constraint if exists partner_showcase_relationship_type_check;
alter table public.partner_showcase
  add constraint partner_showcase_relationship_type_check
  check (relationship_type in (
    'partner',
    'strategic_collaborator',
    'client',
    'institutional_ecosystem',
    'regulatory_reference',
    'technology_provider',
    'founding_company'
  ));

insert into public.partner_showcase (
  slug,
  name,
  relationship_type,
  short_label,
  description,
  logo_url,
  website_url,
  compliance_note,
  is_featured,
  is_published,
  sort_order
) values (
  'start-to-up',
  'Start To Up',
  'founding_company',
  'Founding company & product developer',
  'ResKonnect is a Start To Up product. Start To Up is the founding company and product developer behind the ResKonnect platform.',
  'data:image/webp;base64,',
  'https://www.start-to-up.co.za/',
  'Relationship supplied by ResKonnect: Start To Up is the founding company and product developer behind ResKonnect.',
  true,
  true,
  0
)
on conflict (slug) do update set
  name = excluded.name,
  relationship_type = excluded.relationship_type,
  short_label = excluded.short_label,
  description = excluded.description,
  logo_url = excluded.logo_url,
  website_url = excluded.website_url,
  compliance_note = excluded.compliance_note,
  is_featured = excluded.is_featured,
  is_published = excluded.is_published,
  sort_order = excluded.sort_order,
  updated_at = now();
